{"file_path":"src/graph.js","content":"/** Ordering the task graph. */

/** A cycle a depth-first search found in the dependency graph. */
export class CycleError extends Error {
  /**
   * @param {string[]} cycle - the cycle's names, starting and ending on the re-entered task.
   */
  constructor(cycle) {
    super(`cycle: ${cycle.join(' -> ')}`)
    this.name = 'CycleError'
    this.cycle = cycle
  }
}

/**
 * The first cycle a depth-first search finds, starting from each task in ascending name order
 * and walking each task's dependencies in ascending name order.
 * @param {Map<string, {needs: string[]}>} tasks - the parsed tasks.
 * @returns {string[]|null} the cycle's names, or null when there is none.
 */
function findCycle(tasks) {
  const names = [...tasks.keys()].sort()
  const state = new Map(names.map(name => [name, 0]))
  const stack = []

  function visit(name) {
    state.set(name, 1)
    stack.push(name)
    const deps = [...tasks.get(name).needs].sort()
    for (const dep of deps) {
      if (state.get(dep) === 1) return [...stack.slice(stack.indexOf(dep)), dep]
      if (state.get(dep) === 0) {
        const found = visit(dep)
        if (found !== null) return found
      }
    }
    state.set(name, 2)
    stack.pop()
    return null
  }

  for (const name of names) {
    if (state.get(name) === 0) {
      const found = visit(name)
      if (found !== null) return found
    }
  }
  return null
}

/**
 * The tasks in run order: repeatedly the lexicographically smallest task whose
 * dependencies have all been emitted.
 * @param {Map<string, {needs: string[]}>} tasks - the parsed tasks.
 * @returns {string[]} the names in run order.
 * @throws {CycleError} when the dependency graph has a cycle.
 */
export function order(tasks) {
  const cycle = findCycle(tasks)
  if (cycle !== null) throw new CycleError(cycle)
  const remaining = new Set(tasks.keys())
  const emitted = new Set()
  const out = []
  while (remaining.size > 0) {
    const ready = [...remaining].filter(name => tasks.get(name).needs.every(need => emitted.has(need))).sort()
    remaining.delete(ready[0])
    emitted.add(ready[0])
    out.push(ready[0])
  }
  return out
}
"}

