const DIGEST = /^[0-9a-f]{8}$/

/** One malformed line of a snapshot, carrying the message the specification words. */
export class SnapshotError extends Error {
  /**
   * @param {string} message - the full message, without the `error: ` prefix.
   */
  constructor(message) {
    super(message)
    this.name = 'SnapshotError'
  }
}

/**
 * Parse a digest snapshot into the digest recorded for each path.
 * @param {string} text - the whole snapshot file.
 * @param {string} path - the snapshot's own path, as it names itself in a failure.
 * @returns {Map<string, string>} the digest recorded for each path.
 */
export function parseSnapshot(text, path) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  const digests = new Map()
  for (const [index, raw] of lines.entries()) {
    const line = index + 1
    const text = raw.trim()
    if (text === '' || text.startsWith('#')) continue
    const words = text.split(/\s+/u)
    if (words.length !== 2) throw new SnapshotError(`${path}: line ${line}: expected <path> <digest>`)
    const [recorded, digest] = words
    if (!DIGEST.test(digest)) throw new SnapshotError(`${path}: line ${line}: invalid digest ${digest}`)
    if (digests.has(recorded)) throw new SnapshotError(`${path}: line ${line}: path ${recorded} is recorded twice`)
    digests.set(recorded, digest)
  }
  return digests
}
"}

